-- ----------sql1------------
-- 2147483648, 2147483648, 2147483648, 1
SELECT D.FORENAME, D.SURNAME, D.NATIONALITY, MAX(DS.POINTS) AS MAX_POINTS FROM DRIVERS AS D INNER JOIN DRIVERSTANDINGS AS DS ON D.DRIVERID = DS.DRIVERID GROUP BY D.DRIVERID ORDER BY SUM(DS.WINS) DESC LIMIT 1;
-- ----------sql2------------
-- 2147483648, 2147483649, 2147483649, 2
SELECT T1.FORENAME, T1.SURNAME, T1.NATIONALITY, MAX(T2.POINTS) FROM DRIVERS AS T1 INNER JOIN DRIVERSTANDINGS AS T2 ON T2.DRIVERID = T1.DRIVERID WHERE T2.WINS >= 1 GROUP BY T1.FORENAME, T1.SURNAME, T1.NATIONALITY ORDER BY COUNT(T2.WINS) DESC LIMIT 1;

